import { Platform, TextInputProps } from 'react-native'
import {
	CodeField,
	useClearByFocusCell
} from 'react-native-confirmation-code-field'
import { OTPCell } from './OTPCell'
import { useEffect } from 'react'
import Animated from 'react-native-reanimated'
import { useShake } from '@/utils/hooks/useShake'
import { useSignInWithMagicLinkCodeMutation } from '@/generated/graphql'
import { useAuthStore } from '@/stores/authStore'
import { defineStyles } from '@/utils/defineStyles'
import { BlurOnFulfillRef } from '../EnterEmailScreen'
import { redirectAfterAuth } from '@/utils/redirect-after-auth'

const autoComplete = Platform.select<TextInputProps['autoComplete']>({
	ios: 'one-time-code',
	android: 'sms-otp'
})

type OTPInputContainerProps = {
	email: string
	otpInputRef: BlurOnFulfillRef
	otpInput: string
	setOtpInput: (otpInput: string) => void
	otpError: boolean
	setOtpError: (otpError: boolean) => void
}

export const OTPInputContainer = ({
	email,
	otpInputRef,
	otpInput,
	setOtpInput,
	otpError,
	setOtpError
}: OTPInputContainerProps) => {
	const { setAuth } = useAuthStore()
	const { errorShakeStyle, shake } = useShake(10, 100)

	const [signInWithMagicLinkCode] = useSignInWithMagicLinkCodeMutation()

	useEffect(() => {
		if (otpInputRef.current) {
			otpInputRef.current.focus()
		}
	}, [otpInputRef])

	useEffect(() => {
		if (otpInput.length !== 6) return

		setOtpError(false)

		signInWithMagicLinkCode({
			variables: { input: { email, codeAttempt: otpInput } }
		})
			.then(async (data) => {
				if (data.data?.signInWithMagicLinkCode) {
					setAuth(data.data.signInWithMagicLinkCode)
					await redirectAfterAuth()
				} else {
					setOtpError(true)
					shake()
				}
			})
			.catch(() => {
				setOtpError(true)
				shake()
			})
	}, [otpInput, shake, email, setAuth, signInWithMagicLinkCode, setOtpError])

	const handleChangeText = (text: string) => {
		if (text.length < 6) {
			setOtpError(false)
		}
		setOtpInput(text)
	}

	const [props, getCellOnLayoutHandler] = useClearByFocusCell({
		value: otpInput,
		setValue: handleChangeText
	})

	return (
		<Animated.View style={errorShakeStyle}>
			<CodeField
				ref={otpInputRef}
				{...props}
				value={otpInput}
				onChangeText={handleChangeText}
				cellCount={6}
				rootStyle={styles.codeFieldRoot}
				keyboardType="number-pad"
				textContentType="oneTimeCode"
				autoComplete={autoComplete}
				renderCell={({ index, symbol, isFocused }) => {
					return (
						<OTPCell
							key={index}
							symbol={symbol}
							isFocused={isFocused || index === 0}
							getCellOnLayoutHandler={getCellOnLayoutHandler(index)}
							otpError={otpError}
						/>
					)
				}}
			/>
		</Animated.View>
	)
}

const styles = defineStyles({
	codeFieldRoot: {
		justifyContent: 'center',
		alignItems: 'center'
	}
})
